export function ParentComponent({
  propName = "{{propName}}",
  stateValue = "{{stateValue}}",
  childCount = "{{childCount}}",
  accent = "{{accent}}",
}) {
  const n = Number(childCount);
  const children = [0, 1, 2].filter((i) => i < n);
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ border: `2px dashed ${accent}`, borderRadius: 8, padding: 10, fontWeight: 700, textAlign: "center", marginBottom: 12 }}>Parent &mdash; owns {propName}={stateValue}</div>
      <div style={{ display: "flex", gap: 8 }}>
        {children.map((i) => (
          <div key={i} style={{ flex: 1, borderRadius: 8, padding: 10, textAlign: "center", fontWeight: 700, boxSizing: "border-box", background: accent }}>
            Child
            <small style={{ display: "block", fontWeight: 400, fontSize: 10, marginTop: 3 }}>{propName}={stateValue}</small>
          </div>
        ))}
      </div>
    </div>
  );
}
